            continue
        for f in files:
            if not f.endswith(('.md', '.jsonl', 'lock')):
                continue
            path = os.path.join(root_dir, f)
            try:
                with open(path) as fh:
                    content = fh.read()
                    # Look for task-like IDs (hex strings of 8 chars)
                    matches = re.findall(r'task-[a-f0-9]{8,}', content)
                    if matches:
                        found.append((path, matches))
            except:
                pass
    return found

